 try{const response=await fetch(BASE+'/rest/v1/rpc/study_ministry_write',{method:'POST',headers:{...headers,'Content-Type':'application/json'},signal:controller.signal,body:JSON.stringify({p_password:state.password,p_person:state.person,p_month:state.month,p_revision:state.base.revision,p_action:op.action,p_day:op.day,p_value:op.value})});const result=await response.json().catch(()=>null);if(!response.ok){const e=Error(result?.message||'저장하지 못했습니다.');e.code=result?.code;throw e}return result}finally{clearTimeout(timer)}
